/**
 * classify(fv) -> { verdict, score, module }
 */
export function classify(fv) {
  const s = Math.max(0, Math.min(1, score(fv)));
  return {
    verdict: s >= 0.5 ? 'suspicious' : 'safe',
    score: Math.round(s * 1000) / 1000,
    module: 'aitm',
  };
}
